# ===== 光学显微镜补充 =====
{"id":105,"type":"choice","question":"暗视野显微镜（暗场显微镜）的工作原理与主要用途是？","options":{"A":"利用光线在黑暗背景中产生衍射，用于观察活细胞的内部颗粒和运动","B":"利用荧光标记观察蛋白质定位","C":"利用电子束观察超微结构","D":"利用偏振光观察晶体结构"},"answer":"A","explanation":"暗视野显微镜在聚光镜中央加挡光板，使光线不直接进入物镜，视野背景黑暗；样品颗粒对光线产生散射和衍射，在暗背景中发出亮光。常用于观察活细胞（如螺旋体、线粒体等微小颗粒）的形态与运动。","difficulty":2,"tags":["暗视野显微镜","活细胞","衍射"]},
{"id":106,"type":"choice","question":"偏振光显微镜主要用于观察什么？","options":{"A":"具有各向异性（双折射）特性的结构，如细胞骨架纤维、晶体","B":"荧光标记的蛋白质","C":"DNA碱基序列","D":"细胞膜流动性"},"answer":"A","explanation":"偏振光显微镜利用偏振器产生偏振光照射样品，具有双折射（各向异性）特性的结构（如肌动蛋白丝、微管、胶原纤维、淀粉粒等）会改变偏振方向，呈现明暗差异，用于研究有序排列的结构。","difficulty":2,"tags":["偏振光显微镜","双折射","细胞骨架"]},
{"id":107,"type":"choice","question":"倒置显微镜与普通显微镜的主要区别是？","options":{"A":"光源在物镜下方，适合观察培养皿中贴壁生长的活细胞","B":"放大倍数更高","C":"使用电子束","D":"只能观察固定样品"},"answer":"A","explanation":"倒置显微镜的光源和聚光镜位于载物台下方、物镜在上方，物镜从培养皿底部向上观察，特别适合观察培养皿中贴壁生长的活细胞，是细胞培养观察的常规工具。","difficulty":1,"tags":["倒置显微镜","细胞培养"]},
{"id":108,"type":"choice","question":"双光子显微镜相比普通共聚焦显微镜的主要优势是？","options":{"A":"使用两个光子同时激发荧光分子，光毒性小、穿透深度大","B":"不需要激光","C":"分辨率达到原子水平","D":"无需任何荧光标记"},"answer":"A","explanation":"双光子显微镜利用长波长（红外）激光的两个光子同时激发荧光分子，只有焦点处光子密度足够高才能激发，天然实现三维定位；红外光散射小、穿透深（可达数百微米至毫米），光毒性小，适合活体深层组织成像。","difficulty":3,"tags":["双光子显微镜","活体成像","光毒性"]},
# ===== 电镜补充 =====
{"id":109,"type":"choice","question":"冷冻蚀刻（冷冻复型）技术主要用于研究什么？","options":{"A":"生物膜脂双分子层内部的蛋白颗粒分布","B":"蛋白质氨基酸序列","C":"DNA碱基组成","D":"细胞膜流动性系数"},"answer":"A","explanation":"冷冻蚀刻将样品快速冷冻后沿膜脂双分子层疏水内部断裂，暴露出膜内蛋白颗粒，经铂-碳投影复型后在电镜下观察，可研究生物膜内部的蛋白颗粒分布（如质膜内蛋白、缝隙连接等）。","difficulty":2,"tags":["冷冻蚀刻","生物膜","电镜"]},
{"id":110,"type":"choice","question":"电子显微镜的成像对比度（反差）主要来源于？","options":{"A":"样品不同部位对电子散射能力的差异","B":"样品自身的颜色差异","C":"荧光强度差异","D":"样品折射率差异"},"answer":"A","explanation":"电镜图像的反差来自样品不同结构对电子束散射能力的不同：散射电子能力强的区域（如重金属染色部位）电子少、图像暗，散射弱区域图像亮。因此电镜样品需用重金属盐（如铀、铅）染色增强反差。","difficulty":2,"tags":["电镜","反差","电子散射"]},
{"id":111,"type":"choice","question":"X射线晶体学技术在细胞生物学中的应用是？","options":{"A":"解析蛋白质等生物大分子的高分辨率三维结构","B":"观察细胞器超微结构","C":"分离细胞组分","D":"测量细胞膜电位"},"answer":"A","explanation":"X射线晶体学通过分析晶体对X射线的衍射图样解析生物大分子的原子分辨率三维结构，是结构生物学经典技术（如血红蛋白、核糖体结构）。需样品能形成晶体，这是其相对冷冻电镜的局限。","difficulty":2,"tags":["X射线晶体学","结构生物学"]},
{"id":112,"type":"choice","question":"下列哪项是冷冻电子显微镜（Cryo-EM）相比X射线晶体学的优势？","options":{"A":"样品无需结晶，可在近生理状态玻璃态冰中直接成像","B":"分辨率一定更高","C":"只需要光学显微镜","D":"不需要任何样品处理"},"answer":"A","explanation":"冷冻电镜把样品快速冷冻在玻璃态冰中，无需结晶，可在近生理状态下获取生物大分子结构，并支持动态构象研究；而X射线晶体学要求样品形成晶体（很多膜蛋白难以结晶）。","difficulty":2,"tags":["冷冻电镜","X射线晶体学","玻璃态冰"]},
# ===== 细胞组分分析:层析与电泳 =====
{"id":113,"type":"choice","question":"凝胶过滤层析（分子筛层析）分离蛋白质的依据是？","options":{"A":"蛋白质分子大小（能否进入凝胶颗粒孔内）","B":"蛋白质所带电荷","C":"蛋白质与配体的亲和力","D":"蛋白质的等电点"},"answer":"A","explanation":"凝胶过滤层析的凝胶颗粒内部有大小不一的孔隙，大分子不能进入孔内从颗粒间流过，先被洗脱；小分子进入孔内路径长，后被洗脱。因此按分子大小分离，大分子先流出，小分子后流出。","difficulty":2,"tags":["凝胶过滤层析","分子筛","蛋白质分离"]},
{"id":114,"type":"choice","question":"离子交换层析分离蛋白质的依据是？","options":{"A":"蛋白质在不同pH下所带净电荷的差异","B":"蛋白质分子大小","C":"蛋白质疏水性","D":"蛋白质颜色"},"answer":"A","explanation":"离子交换层析利用固定相（离子交换树脂）与流动相中带相反电荷蛋白质的可逆结合：蛋白质在特定pH下净电荷不同，与树脂结合力不同，通过提高盐浓度或改变pH梯度依次洗脱，按电荷差异分离。","difficulty":2,"tags":["离子交换层析","电荷","蛋白质分离"]},
{"id":115,"type":"choice","question":"亲和层析分离蛋白质的基本原理是？","options":{"A":"利用蛋白质与其配体（如抗体、底物、金属离子）间的特异性亲和结合","B":"按分子大小筛分","C":"按等电点分离","D":"按疏水性分离"},"answer":"A","explanation":"亲和层析将配体（抗体、受体、底物类似物、Ni²⁺等）共价偶联到基质上，目标蛋白特异性结合于柱上，其他蛋白流出，再用高浓度竞争剂或改变pH洗脱目标蛋白，纯化倍数高，是蛋白质纯化的高效手段。","difficulty":2,"tags":["亲和层析","特异性","纯化"]},
{"id":116,"type":"choice","question":"SDS-PAGE（十二烷基硫酸钠-聚丙烯酰胺凝胶电泳）中，蛋白质的迁移速度主要取决于？","options":{"A":"蛋白质分子量","B":"蛋白质天然电荷","C":"蛋白质等电点","D":"蛋白质疏水性"},"answer":"A","explanation":"SDS是阴离子去污剂，能破坏蛋白质非共价作用并以其固定比例（约1.4 g SDS/g蛋白）结合蛋白质，使蛋白质变性并带均匀的负电荷；β-巯基乙醇打断二硫键。此时蛋白质迁移率仅取决于分子量大小，可用于测定分子量。","difficulty":2,"tags":["SDS-PAGE","电泳","分子量"]},
{"id":117,"type":"choice","question":"等电聚焦电泳分离蛋白质的依据是？","options":{"A":"蛋白质的等电点（pI）差异","B":"蛋白质分子量","C":"蛋白质疏水性","D":"蛋白质浓度"},"answer":"A","explanation":"等电聚焦在凝胶中预先建立pH梯度，蛋白质在电场中迁移至其等电点（净电荷为零）位置即停止聚焦成窄带。分辨率高，可区分pI差异极小的蛋白质，常作为二维电泳第一向。","difficulty":2,"tags":["等电聚焦","等电点","二维电泳"]},
{"id":118,"type":"choice","question":"二维电泳（2D-PAGE）的第一向和第二向分别依据什么分离蛋白质？","options":{"A":"第一向按等电点（等电聚焦），第二向按分子量（SDS-PAGE）","B":"第一向按分子量，第二向按等电点","C":"两向都按分子量","D":"两向都按电荷"},"answer":"A","explanation":"二维电泳第一向为等电聚焦（按等电点分离），第二向为SDS-PAGE（按分子量分离），两个维度正交，可将数千种蛋白质分开，形成蛋白质点阵图谱，是蛋白质组学经典分离手段。","difficulty":2,"tags":["二维电泳","等电聚焦","蛋白质组学"]},
{"id":119,"type":"choice","question":"琼脂糖凝胶电泳主要用于分离什么？","options":{"A":"DNA、RNA等核酸分子","B":"蛋白质","C":"脂类","D":"多糖"},"answer":"A","explanation":"琼脂糖凝胶孔径较大，适合分离核酸分子（DNA片段、RNA），按分子大小迁移，通过溴化乙锭（EB）等核酸染料染色后在紫外灯下观察，是分子克隆和PCR产物分析的常规方法。","difficulty":1,"tags":["琼脂糖凝胶电泳","核酸"]},
{"id":120,"type":"choice","question":"Western blot（蛋白质印迹）技术的主要流程是？","options":{"A":"SDS-PAGE分离蛋白→转膜→抗体杂交→显色检测","B":"琼脂糖凝胶分离DNA→转膜→探针杂交","C":"离心分离蛋白→直接显色","D":"PCR扩增→琼脂糖电泳"},"answer":"A","explanation":"Western blot流程：①SDS-PAGE按分子量分离蛋白；②电转将蛋白转移到硝酸纤维素膜或PVDF膜上；③封闭后用特异性一抗杂交，再用酶或荧光标记二抗杂交；④显色或化学发光检测。用于检测特定蛋白的存在、分子量及相对含量。","difficulty":2,"tags":["Western blot","蛋白质印迹","抗体"]},
{"id":121,"type":"choice","question":"Southern blot与Northern blot的检测对象分别是？","options":{"A":"Southern blot检测DNA，Northern blot检测RNA","B":"Southern blot检测RNA，Northern blot检测DNA","C":"两者都检测蛋白质","D":"两者都检测脂类"},"answer":"A","explanation":"Southern blot用标记探针检测膜上DNA片段（DNA印迹），Northern blot检测RNA（RNA印迹），Western blot检测蛋白质。三者名称源自发明者姓名（Southern、Northern、Western），是分子生物学基本检测技术。","difficulty":1,"tags":["Southern blot","Northern blot","核酸"]},
# ===== 蛋白质分离纯化与酶活力测定(考纲缺口) =====
{"id":122,"type":"choice","question":"蛋白质粗提中常用的盐析法（salting out）原理是？","options":{"A":"高浓度中性盐（如硫酸铵）夺取蛋白质表面水化层，使蛋白质沉淀","B":"用酸使蛋白质变性沉淀","C":"利用蛋白质密度差离心沉淀","D":"用去垢剂溶解蛋白质"},"answer":"A","explanation":"盐析利用高浓度中性盐（常用硫酸铵）竞争结合水分子，破坏蛋白质表面的水化层并屏蔽电荷，降低溶解度使蛋白质沉淀。盐析一般不破坏蛋白质天然构象，可逆，常用于蛋白质初步分离。","difficulty":2,"tags":["盐析","蛋白质分离","硫酸铵"]},
{"id":123,"type":"choice","question":"透析（dialysis）和超滤（ultrafiltration）在蛋白质纯化中的作用是？","options":{"A":"去除小分子杂质（盐、小肽）或浓缩蛋白质溶液","B":"按分子量精确分离不同蛋白质","C":"测定蛋白质等电点","D":"使蛋白质变性"},"answer":"A","explanation":"透析利用半透膜允许小分子（盐离子、小肽）自由扩散透过而蛋白质大分子不能透过，用于去除盐等小分子杂质；超滤利用加压使水和小分子透过超滤膜，截留蛋白质，用于浓缩蛋白质溶液。","difficulty":2,"tags":["透析","超滤","脱盐","浓缩"]},
{"id":124,"type":"choice","question":"酶活力（enzyme activity）的国际单位（IU）定义为？","options":{"A":"在最适条件下每分钟催化转化1微摩尔底物所需的酶量","B":"每毫克蛋白质所含的酶活力","C":"酶促反应的最大速度","D":"酶蛋白的分子量"},"answer":"A","explanation":"酶活力单位IU定义为：在最适条件（最适温度、pH和底物浓度）下，每分钟催化1微摩尔（μmol）底物转化为产物所需的酶量。测定酶活力是酶提纯过程中追踪目标酶的基本手段。","difficulty":2,"tags":["酶活力","国际单位","IU"]},
{"id":125,"type":"choice","question":"酶的比活力（specific activity）的定义及其在纯化中的意义是？","options":{"A":"每毫克蛋白质所含的酶活力单位数，比活力越高说明纯度越高","B":"酶促反应的Km值","C":"每毫升酶液的总活力","D":"酶的分子量"},"answer":"A","explanation":"比活力=总酶活力/总蛋白质含量（U/mg蛋白），是衡量酶纯度的标准指标。提纯过程中比活力逐渐升高，纯化倍数=各步比活力/起始比活力，比活力越高表明目标酶越纯。","difficulty":2,"tags":["比活力","酶纯度","纯化倍数"]},
{"id":126,"type":"choice","question":"测定酶活力时，通常需要控制的条件不包括？","options":{"A":"最适温度和pH","B":"底物浓度足够（饱和）","C":"测定反应初速度","D":"用去垢剂将酶变性"},"answer":"D","explanation":"酶活力测定需在最适温度、pH和饱和底物浓度下测定反应初速度（此时产物量随时间线性增加），以保证测得的活力反映酶量。将酶变性后无法测定活力。","difficulty":2,"tags":["酶活力测定","初速度","最适条件"]},
# ===== 免疫学技术补充 =====
{"id":127,"type":"choice","question":"ELISA（酶联免疫吸附测定）技术的基本原理是？","options":{"A":"抗体（或抗原）固相化后与待测抗原（或抗体）结合，用酶标抗体催化底物显色定量","B":"用放射性同位素标记抗体检测","C":"用电泳分离后再检测","D":"用荧光显微镜直接观察"},"answer":"A","explanation":"ELISA将抗体（或抗原）包被在固相（微孔板）表面，加入待测样本使其与固相抗体特异结合，再加入酶标抗体形成夹心复合物，加底物后酶催化显色，颜色深浅与待测物含量成正比，可用于定量检测抗原或抗体。","difficulty":2,"tags":["ELISA","酶标抗体","定量检测"]},
{"id":128,"type":"choice","question":"免疫沉淀（IP）与免疫共沉淀（Co-IP）的区别在于？","options":{"A":"IP沉淀单个目标蛋白，Co-IP沉淀目标蛋白及其相互作用的伙伴蛋白","B":"IP使用多克隆抗体，Co-IP使用单克隆抗体","C":"IP在体外进行，Co-IP在体内进行","D":"IP检测DNA，Co-IP检测RNA"},"answer":"A","explanation":"免疫沉淀（IP）用抗体沉淀并富集单个目标蛋白（结合SDS-PAGE/WB分析）；免疫共沉淀（Co-IP）用温和裂解保留复合体，抗体沉淀目标蛋白时同时沉降与其相互作用的伙伴蛋白，用于研究蛋白质相互作用。","difficulty":2,"tags":["免疫沉淀","Co-IP","蛋白质相互作用"]},
# ===== 细胞培养补充 =====
{"id":129,"type":"choice","question":"哺乳动物细胞体外培养时，通常需要在CO₂培养箱中维持什么样的气体环境？","options":{"A":"5% CO₂ + 95%空气（37℃）","B":"100% CO₂","C":"纯氮气","D":"真空环境"},"answer":"A","explanation":"哺乳动物细胞培养通常采用37℃、5% CO₂ + 95%空气的培养箱。CO₂与培养基中的碳酸氢钠缓冲对维持pH约7.2~7.4（多数培养基的碳酸氢盐缓冲体系需要CO₂）。","difficulty":1,"tags":["细胞培养","CO2培养箱","培养条件"]},
{"id":130,"type":"choice","question":"细胞培养中防止微生物污染的主要措施不包括？","options":{"A":"无菌操作（超净台、无菌器具）","B":"培养基中添加青霉素-链霉素等抗生素","C":"定期更换培养基并检测支原体污染","D":"把培养箱温度提高到50℃"},"answer":"D","explanation":"50℃高温会杀死哺乳动物细胞。防止污染的措施包括无菌操作、抗生素添加、定期换液和支原体检测等。支原体污染难以肉眼发现，是细胞培养最隐蔽的污染源。","difficulty":1,"tags":["细胞培养","无菌操作","污染"]},
{"id":131,"type":"choice","question":"细胞同步化是指？","options":{"A":"使培养细胞群体处于同一细胞周期时相的技术","B":"使细胞同时死亡的技术","C":"把不同来源细胞混合培养","D":"提高细胞增殖速度的技术"},"answer":"A","explanation":"细胞同步化通过药物阻断（如双胸苷阻断S期、秋水仙素/诺考达唑阻断M期）或血清饥饿（使细胞进入G0/G1期）、有丝分裂摇落法（shake-off）等技术，使群体细胞处于同一周期时相，便于研究特定时相的事件。","difficulty":2,"tags":["细胞同步化","细胞周期","双胸苷"]},
{"id":132,"type":"choice","question":"克隆化培养（克隆形成实验）的主要目的是？","options":{"A":"从单个细胞出发培养形成克隆，评估细胞的增殖能力和纯度","B":"使细胞无限增殖","C":"检测细胞是否被病毒感染","D":"测定细胞大小"},"answer":"A","explanation":"克隆化培养将细胞稀释至单细胞接种，单个细胞增殖形成细胞克隆（集落），通过克隆形成率（集落数/接种细胞数）评估细胞的增殖和存活能力，也用于获得遗传性状均一的细胞克隆。","difficulty":2,"tags":["克隆化培养","克隆形成","增殖能力"]},
# ===== 分子与单细胞技术补充 =====
{"id":133,"type":"choice","question":"PCR（聚合酶链式反应）技术的基本原理是？","options":{"A":"以DNA为模板，在引物和耐热DNA聚合酶作用下，通过变性-退火-延伸循环指数扩增特定DNA片段","B":"用抗体捕获DNA","C":"通过离心富集DNA","D":"用限制酶切割DNA"},"answer":"A","explanation":"PCR循环包括：①变性（约95℃解开双链）；②退火（引物与模板互补结合，约55~65℃）；③延伸（耐热聚合酶如Taq酶在约72℃合成新链）。每轮循环DNA量加倍，25~35轮后可扩增数百万倍，是基因分析的基础技术。","difficulty":2,"tags":["PCR","DNA扩增","Taq酶"]},
{"id":134,"type":"choice","question":"光镊（光学镊子）技术在细胞生物学中的应用是？","options":{"A":"用聚焦激光束的辐射压力捕获和操控微米级粒子（如细胞、细胞器）","B":"用光激发荧光","C":"用光切割DNA","D":"用光测量温度"},"answer":"A","explanation":"光镊利用高度聚焦的激光束对微小粒子产生梯度力，可非接触捕获和移动细胞、细胞器、分子马达等，并可测量分子间作用力（皮牛级），是研究分子马达力学、细胞力学的重要工具。","difficulty":3,"tags":["光镊","激光","单分子"]},
